{
  "a_sentences": [
    {
      "a_text": "P1 Streitig ist, ob die Vorinstanz Bundesrecht verletzte, indem sie einen Anspruch auf Vergütung der von August 2022 bis zur Anstellung einer Hilfsperson im Frühjahr 2023 von den Eltern des Versicherten selbst erbrachten Hilfe im Rahmen des zugesprochenen Assistenzbeitrags verneinte.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "P2 Nach Art. 42quinquies IVG werden Assistenzbeiträge nur für Hilfeleistungen gewährt, die von einer natürlichen, nicht zu den engeren Familienangehörigen gehörenden Person im Rahmen eines Arbeitsvertrags erbracht werden.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "P3 Nach Art. 42quinquies IVG werden Assistenzbeiträge nur für Hilfeleistungen ausgerichtet, die von einer natürlichen, nicht zu den engeren Familienangehörigen gehörenden Person im Rahmen eines Arbeitsvertrags erbracht werden.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "P4 Die Informationspflicht nach Art. 27 Abs. 1 ATSG wird regelmässig durch die Abgabe von Informationsbroschüren, Merkblättern und Wegleitungen sowie Internetinformationen erfüllt.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "P5 Art. 42septies Abs. 1 IVG bestimmt, dass der Anspruch auf einen Assistenzbeitrag frühestens im Zeitpunkt der Geltendmachung entsteht.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "P6 Für Zeiträume ohne Anstellung einer Assistenzperson besteht folglich kein Anspruch auf Assistenzbeitrag, selbst wenn die übrigen Voraussetzungen erfüllt sind.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "P7 Die Vorinstanz verletzte die Informations- und Beratungspflicht nach Art. 27 ATSG nicht, da die IV-Stelle die Informationspflicht durch Merkblätter und Internetinformationen erfüllt hat und keine weitergehende Beratungspflicht bestand.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "P8 Die Vorinstanz verletzte zusammenfassend kein Bundesrecht, indem sie erkannte, dass während der Anspruchsabklärung von den Eltern des Versicherten erbrachte Hilfeleistungen nicht mittels Assistenzbeitrag zu vergüten sind.",
      "b_propositions": ["P8"]
    }
  ]
}
